function renderShortcutSettings(){const container=$('#shortcutSettingsList');container.innerHTML=shortcutDefinitions.map(({id,label})=>`<div><span>${esc(label)}</span><div class="shortcut-actions"><button type="button" class="shortcut-capture" data-shortcut-action="${id}" aria-label="Cambiar atajo: ${esc(label)}"><span>${esc(editorShortcuts[id].map(formatShortcut).join(' / ')||'Sin asignar')}</span><span>Cambiar</span></button><button type="button" class="shortcut-clear" data-shortcut-clear="${id}" aria-label="Quitar atajo: ${esc(label)}">Quitar</button></div></div>`).join('')}
