function noteToVex(n){return `${(n.name||'C').toLowerCase()}/${n.octave??4}`}
function noteBeats(n){const base={w:4,h:2,q:1,'8':.5,'16':.25}[n.duration||'q']||1;return base*(n.dotted?1.5:1)}
function scoreMeasures(){const capacity=state.meter.numerator*4/state.meter.denominator;const measures=[{indices:[],beats:0}];state.notes.forEach((note,index)=>{const beats=noteBeats(note);let bar=measures[measures.length-1];if(bar.indices.length&&bar.beats+beats>capacity+.001){bar={indices:[],beats:0};measures.push(bar)}bar.indices.push(index);bar.beats+=beats});return measures}
function snapshot(){return JSON.stringify({notes:state.notes,ties:state.ties,meter:state.meter,tempo:$('#tempoValue')?.textContent||'80'})}
function restoreSnapshot(value){const saved=JSON.parse(value);state.notes=Array.isArray(saved.notes)?saved.notes:[];state.ties=Array.isArray(saved.ties)?saved.ties:[];state.meter=saved.meter||{numerator:4,denominator:4};if($('#tempoValue'))$('#tempoValue').textContent=String(saved.tempo||80);if($('#meterNumerator'))$('#meterNumerator').value=String(state.meter.numerator);if($('#meterDenominator'))$('#meterDenominator').value=String(state.meter.denominator);state.selectedNotes.clear();renderScore();updateSelectedNoteProperties()}
function pushHistory(){state.history.push(snapshot());if(state.history.length>80)state.history.shift();state.redo=[]}
