async function saveRecordingBlob(){const cid=$('#recordComposition').value;if(!cid){toast('Selecciona una composición antes de grabar.');return}const blob=new Blob(state.recordChunks,{type:state.recordChunks[0]?.type||'audio/webm'});if(!blob.size){toast('La grabación quedó vacía; comprueba el micrófono e inténtalo de nuevo.');return}const ext=blob.type.includes('ogg')?'ogg':blob.type.includes('mp4')?'m4a':'webm';if(state.recordedUrl)URL.revokeObjectURL(state.recordedUrl);const url=URL.createObjectURL(blob);state.recordedUrl=url;$('#recordAudio').src=url;$('#recordAudio').hidden=false;$('#downloadRecordedBtn').disabled=false;const fd=new FormData();fd.append('audio',blob,'grabacion.'+ext);fd.append('duracion',((Date.now()-state.recordStart)/1000).toFixed(2));try{await api('/api/compositions/'+cid+'/recordings',{method:'POST',body:fd});$('#recordMessage').textContent='Grabación guardada correctamente.';await loadRecordings(cid);toast('Grabación guardada.')}catch(e){toast(e.message)}}$('#playRecordedBtn').onclick=()=>state.recordedUrl?$('#recordAudio').play():toast('Todavía no hay una grabación disponible.');$('#downloadRecordedBtn').onclick=()=>{if(!state.recordedUrl)return toast('Todavía no hay una grabación disponible.');const a=document.createElement('a');a.href=state.recordedUrl;a.download='lyrics-grabacion.'+(state.recordChunks[0]?.type.includes('ogg')?'ogg':state.recordChunks[0]?.type.includes('mp4')?'m4a':'webm');a.click()};
async function loadRecordings(cid){const list=$('#recordingList');if(!list)return;if(!cid){list.innerHTML='';return}try{const d=await api('/api/compositions/'+cid+'/recordings');list.innerHTML=(d.recordings||[]).map(r=>`<div class="recording-history"><span>${esc(formatTime(r.duracion||0))} · ${esc(r.fecha||'')}</span><audio controls preload="none" src="/uploads/${encodeURIComponent(r.archivo_audio)}"></audio></div>`).join('')||'<small>No hay grabaciones guardadas para esta composición.</small>'}catch(e){list.textContent='No se pudieron cargar las grabaciones: '+e.message}}
