function noteAtStaffPosition(event,canvas){const svg=canvas.querySelector('svg');if(!svg)return null;const rect=svg.getBoundingClientRect();const y=(event.clientY-rect.top)*(260/rect.height);const steps=Math.max(0,Math.min(14,Math.round((82-y)/5)));const index=2+steps;return{name:['C','D','E','F','G','A','B'][index%7],octave:4+Math.floor(index/7)}}
