function renderLibrary(){const q=($('#librarySearch').value||'').toLowerCase(),instrument=$('#libraryInstrument').value,difficulty=$('#libraryDifficulty').value,genre=$('#libraryGenre').value;const rows=state.library.filter(x=>(!q||[x.titulo,x.compositor,x.proyecto,x.instrumento].join(' ').toLowerCase().includes(q))&&(!instrument||x.instrumento===instrument)&&(!difficulty||x.dificultad===difficulty)&&(!genre||x.genero===genre)&&(state.libraryFilter!=='favorites'||x.favorita)&&(state.libraryFilter!=='mine'||x.creador_id===state.user?.id_usuario));$('#libraryCards').innerHTML=rows.length?rows.map(x=>`<article class="library-card"><div class="library-score">𝄞 ♩ ♪ ♫</div><h3>${esc(x.titulo)}</h3><p>${esc(x.compositor)} · ${esc(x.proyecto)}</p><span class="tag">${esc(x.instrumento||'Instrumento sin definir')}</span> <span class="tag">${esc(x.dificultad||'Dificultad sin definir')}</span><div class="library-actions"><button class="ghost" data-open-score="${x.id_composicion}" data-project="${x.id_proyecto}">Abrir partitura</button><button class="ghost" data-favorite-score="${x.id_composicion}" aria-pressed="${x.favorita?'true':'false'}">${x.favorita?'★ Favorita':'☆ Favorito'}</button></div></article>`).join(''):'<div class="panel-card" style="grid-column:1/-1;text-align:center;padding:32px">No hay partituras que coincidan con estos filtros.</div>';$$('[data-library-filter]').forEach(b=>b.classList.toggle('active',b.dataset.libraryFilter===state.libraryFilter));$$('[data-open-score]').forEach(b=>b.onclick=()=>openLibraryScore(Number(b.dataset.openScore),Number(b.dataset.project)));$$('[data-favorite-score]').forEach(b=>b.onclick=async()=>{const item=state.library.find(x=>x.id_composicion===Number(b.dataset.favoriteScore));if(!item)return;try{const favorite=!item.favorita;await api(`/api/compositions/${item.id_composicion}/favorite`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({favorita:favorite})});item.favorita=favorite;renderLibrary()}catch(e){toast(e.message)}})}
